<?php
require_once __DIR__ . '/../../config/database.php';
$pdo->exec("CREATE TABLE IF NOT EXISTS drivers (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,phone VARCHAR(20) NOT NULL,license_number VARCHAR(80) NOT NULL UNIQUE,status ENUM('active','inactive') NOT NULL DEFAULT 'active',address TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_drivers_status_name(status,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$pdo->exec("CREATE TABLE IF NOT EXISTS vehicles (id INT AUTO_INCREMENT PRIMARY KEY,registration_number VARCHAR(30) NOT NULL UNIQUE,vehicle_type VARCHAR(100) NOT NULL,make_model VARCHAR(120) NULL,capacity INT NOT NULL DEFAULT 1,status ENUM('active','inactive','maintenance') NOT NULL DEFAULT 'active',driver_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_vehicles_status_type(status,vehicle_type),FOREIGN KEY(driver_id) REFERENCES drivers(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$pdo->exec("CREATE TABLE IF NOT EXISTS mobile_devices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,device_token VARCHAR(512) NOT NULL,platform ENUM('android','ios','web','unknown') NOT NULL DEFAULT 'unknown',app_version VARCHAR(50) NULL,active BOOLEAN NOT NULL DEFAULT TRUE,last_seen_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_mobile_device_token(device_token),INDEX idx_mobile_devices_user_active(user_id,active),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$pdo->exec("CREATE TABLE IF NOT EXISTS role_permissions (id INT AUTO_INCREMENT PRIMARY KEY,role VARCHAR(50) NOT NULL,permission_key VARCHAR(120) NOT NULL,allowed BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_role_permission(role,permission_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
try { $pdo->exec("ALTER TABLE bookings ADD COLUMN driver_id INT NULL, ADD COLUMN vehicle_id INT NULL"); } catch (Throwable $e) {}
try { $pdo->exec("ALTER TABLE bookings ADD CONSTRAINT fk_bookings_driver FOREIGN KEY(driver_id) REFERENCES drivers(id) ON DELETE SET NULL"); } catch (Throwable $e) {}
try { $pdo->exec("ALTER TABLE bookings ADD CONSTRAINT fk_bookings_vehicle FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE SET NULL"); } catch (Throwable $e) {}
